mapper.select:
SELECT identity.id, definition.name, definition.timeout, definition.enabled, definition.description, identity.current_definition_id, identity.current_revision, identity.update_time, (SELECT COUNT(*) FROM ifj_job_definition_node n WHERE n.definition_id = identity.current_definition_id) AS node_count FROM ifj_job identity JOIN ifj_job_definition definition ON definition.id = identity.current_definition_id AND definition.job_id = identity.id AND definition.revision = identity.current_revision
identity.retired = FALSE AND identity.retired_time IS NULL AND identity.id = #{id}
AND definition.name LIKE #{namePattern} ESCAPE '!'
AND definition.enabled = #{enabled}
AND EXISTS ( SELECT 1 FROM ifj_job_definition_group definition_group WHERE definition_group.definition_id = definition.id AND definition_group.group_code = #{group} )
ORDER BY identity.update_time DESC, identity.id DESC

SELECT identity.id, definition.name, definition.timeout, definition.enabled, definition.description, identity.current_definition_id, identity.current_revision, identity.update_time, (SELECT COUNT(*) FROM ifj_job_definition_node n WHERE n.definition_id = identity.current_definition_id) AS node_count FROM ifj_job identity JOIN ifj_job_definition definition ON definition.id = identity.current_definition_id AND definition.job_id = identity.id AND definition.revision = identity.current_revision
identity.retired = FALSE AND identity.retired_time IS NULL AND identity.id = #{id}
AND LOWER(definition.name) LIKE LOWER(#{namePattern}) ESCAPE '!'
AND definition.enabled = #{enabled}
AND EXISTS ( SELECT 1 FROM ifj_job_definition_group definition_group WHERE definition_group.definition_id = definition.id AND definition_group.group_code = #{group} )
ORDER BY identity.update_time DESC, identity.id DESC

